using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Algebra;

internal sealed class AnticommutingInvariantPlaneDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A closed invariant plane gives simultaneous coordinates for an actual irreducible anticommuting triple.",
        H("Closed invariant planes and simultaneous Pauli coordinates"),
        Blocks(Describe.Lean(DescribeId.Create("positive-branch-coordinates"),
            DeclarationHandle.Create("D5/S3/Quantum/Algebra/AnticommutingInvariantPlane.positive_branch_coordinates"),
            H("Coordinates of the actual represented triple"),
            StatementSource.FromAuthor(Disp(Statement())), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("H is an arbitrary nontrivial complete complex inner-product space. R is a unital complex C-star algebra and pi is a unital star-algebra homomorphism from R to the bounded operators on the same H. The selfadjoint elements a,b,d pairwise anticommute and generate R as a norm-closed star algebra. Topological irreducibility means that every closed complex-linear subspace invariant under every pi(r) is zero or all of H. The positive real parameters X,Y describe the actual represented squares; no finite-dimensional premise is imposed.")),
                Paragraph(Text("The construction first normalizes only the represented first two operators. From a nonzero vector x it obtains a nonzero positive eigenvector using x+A(x), or B(x) when that sum vanishes. Normalize this vector to v and put w=B(v). Selfadjointness and anticommutation make v,w orthonormal. Their explicit two-dimensional span W is finite-dimensional and therefore closed.")),
                Paragraph(Text("The selfadjoint operator i A B C commutes with the three generators and then with their closed generated algebra. The selfadjoint topological Schur theorem makes it a real scalar. Consequently C is a scalar multiple of A B, so W is invariant under C as well. The operators and their adjoints preserving W form a closed star subalgebra. This extends invariance through the actual generated algebra. Closed-subspace irreducibility and the unit vector in W imply W=H. The orthonormal pair now gives the single linear isometry equivalence U in the statement, with all three coordinate equations simultaneously.")),
                Paragraph(Text("This applies to the fixed elements of any actual closed generated C-star algebra and its representation; no unrelated finite matrix model replaces them. The coefficient z is any real number, including zero, and X,Y may be unequal. The displayed coordinate maps are X times diag(1,-1), Y times the swap, and z times the matrix with off-diagonal entries -i and i.")),
                Paragraph(Text("In the fixed-triple application, take R to be the actual norm-closed unital star subalgebra B of the ambient algebra generated by a,b,d, and regard these same elements as subtype elements of B. Closedness makes B complete. The closed inclusion of B into the ambient algebra transports star adjoining and topological closure, so the ambient defining equation for B gives precisely the internal generation hypothesis in the theorem. Selfadjointness and all three anticommutation equations pass through that injective inclusion.")),
                Paragraph(Text("The same coordinate map acts on the fixed labels c=X times the unit plus a, j=(ac+ca)/2, rplus=b+d-j and rminus=b-d+j. For every real epsilon, pull the mathematical vector (epsilon,1) back by U. Its c image has coordinates (2X epsilon,0). The rplus image has coordinates (Y-iz-2X squared epsilon,(Y+iz)epsilon), and the rminus image has coordinates (Y+iz+2X squared epsilon,(Y-iz)epsilon). These are algebraic consequences of the simultaneous coordinate equations in the same representation. They introduce no call to an outer response and no normalization of the vector. If d is zero, its represented Pauli coefficient is zero and the same construction still supplies the first two axes.")),
                Paragraph(Text("For an original response problem, a,b,d remain the original fixed elements and d may equal the original response at a,b. The conclusion changes only mathematical representation coordinates. It supplies no descent or extension of that response, no closure of unknown outer outputs, no separating representation family, no zero-X or zero-Y branch, and no affine-axis zero law. Those require their own hypotheses or proofs."))),
            DescribeRole.Theorem))));

    private static Formula I(string s) => F.Id(s);
    private static Formula C(string s, params Formula[] a) => global::StrataLint.Scribe.DefinitionDsl.Call(s,a);
    private static Formula N(int n) => global::StrataLint.Scribe.DefinitionDsl.Num(n);
    private static Formula All(string s, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.ForAll,FormulaIdentifier.Create(s),t,b);
    private static Formula Ex(string s, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.Exists,FormulaIdentifier.Create(s),t,b);
    private static Formula Eq(Formula a, Formula b) => global::StrataLint.Scribe.DefinitionDsl.Equal(a,b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a,FormulaLogicOperator.And,b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a,FormulaLogicOperator.Implies,b);
    private static Formula Mul(Formula a, Formula b) => global::StrataLint.Scribe.DefinitionDsl.Multiply(a,b);
    private static Formula Negate(Formula a) => C("neg",a);
    private static Formula Statement()
    {
        var H=I("H"); var R=I("R"); var p=I("p"); var a=I("a"); var b=I("b"); var d=I("d");
        var X=I("X"); var Y=I("Y"); var z=I("z"); var U=I("U"); var x=I("x");
        Formula P(Formula t)=>C("apply",p,t);
        Formula Op(Formula t)=>C("apply",t,x);
        Formula V(Formula t,int k)=>C("coordinate",C("apply",U,t),N(k));
        Formula Anti(Formula s,Formula t)=>Eq(Mul(s,t),Negate(Mul(t,s)));
        Formula Line(Formula t,Formula s, bool diagonal)=>All("x",H,And(
            Eq(V(Op(P(t)),0),Mul(s,V(x,diagonal?0:1))),
            Eq(V(Op(P(t)),1),Mul(diagonal?Negate(s):s,V(x,diagonal?1:0)))));
        var third=All("x",H,And(
            Eq(V(Op(P(d)),0),Mul(Negate(Mul(C("imaginaryUnit"),z)),V(x,1))),
            Eq(V(Op(P(d)),1),Mul(Mul(C("imaginaryUnit"),z),V(x,0)))));
        var conclusion=Ex("z",C("Real"),Ex("U",C("LinearIsometryEquiv",C("Complex"),H,C("EuclideanSpace",C("Complex"),C("Fin",N(2)))),
            And(Line(a,X,true),And(Line(b,Y,false),third))));
        Formula hypotheses=C("Positive",X);
        Formula[] remaining=[C("Positive",Y),C("IsSelfAdjoint",a),C("IsSelfAdjoint",b),C("IsSelfAdjoint",d),
            Anti(a,b),Anti(a,d),Anti(b,d),
            Eq(Mul(P(a),P(a)),C("smul",C("pow",X,N(2)),N(1))),
            Eq(Mul(P(b),P(b)),C("smul",C("pow",Y,N(2)),N(1))),
            Eq(C("closedStarAdjoin",C("Complex"),C("triple",a,b,d)),C("top")),
            C("IsTopologicallyIrreducible",C("range",p))];
        foreach(var premise in remaining) hypotheses=And(hypotheses,premise);
        Formula result=Imp(hypotheses,conclusion);
        result=All("Y",C("Real"),result);
        result=All("X",C("Real"),result);
        result=All("d",R,result);
        result=All("b",R,result);
        result=All("a",R,result);
        result=All("p",C("StarAlgHom",C("Complex"),R,C("BoundedOperators",H)),result);
        result=Imp(And(C("ComplexHilbertNontrivial",H),C("CStarAlgebra",R)),result);
        return All("H",C("Type"),All("R",C("Type"),result));
    }
}
